SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">أَسْمَاءُ اللّٰهِ الْحُسْنَى (Esmâ-i Hüsnâ Kavramı ve Kur\'ânî Dayanağı)</text>\n  <rect x="40" y="45" width="620" height="65" rx="10" fill="#fef3c7" stroke="#f59e0b" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="15" font-weight="bold" fill="#b45309">وَلِلّٰهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا (الأعراف: ١٨٠)</text>\n  <text x="350" y="95" text-anchor="middle" font-size="12" fill="#78350f">"En güzel isimler Allah\'ındır; öyleyse O\'na o güzel isimlerle dua edin." (A\'râf, 180)</text>\n  <rect x="40" y="125" width="195" height="115" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.6"/>\n  <text x="137" y="150" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">أَسْمَاءُ اللّٰهِ (İzâfet)</text>\n  <text x="137" y="175" text-anchor="middle" font-size="11" fill="#1e3a8a">أَسْمَاءُ : Muzâf (Tamlanan)</text>\n  <text x="137" y="195" text-anchor="middle" font-size="11" fill="#1e3a8a">اللّٰهِ : Muzâfun İleyh (Mecrûr)</text>\n  <text x="137" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">إِسْمٌ kelimesinin çoğulu: أَسْمَاءٌ</text>\n  <rect x="252" y="125" width="195" height="115" rx="10" fill="#ecfdf5" stroke="#10b981" stroke-width="1.6"/>\n  <text x="350" y="150" text-anchor="middle" font-size="13" font-weight="bold" fill="#047857">الْحُسْنَى (Sıfat / İsm-i Tafdîl)</text>\n  <text x="350" y="175" text-anchor="middle" font-size="11" fill="#065f46">أَحْسَنُ (En güzel - Müzekker)</text>\n  <text x="350" y="195" text-anchor="middle" font-size="11" fill="#065f46">الْحُسْنَى (En güzel - Müennes)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#047857">Akılsız çoğul sıfatı müfret müennes</text>\n  <rect x="465" y="125" width="195" height="115" rx="10" fill="#fdf4ff" stroke="#a855f7" stroke-width="1.6"/>\n  <text x="562" y="150" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">تِسْعَةٌ وَتِسْعُونَ اسْمًا</text>\n  <text x="562" y="175" text-anchor="middle" font-size="11" fill="#6b21a8">Hadis-i Şerifte 99 İsim</text>\n  <text x="562" y="195" text-anchor="middle" font-size="11" fill="#6b21a8">مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ</text>\n  <text x="562" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Anlayıp koruyan cennete girer</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">Temel Esmâ-i Hüsnâ Örnekleri ve Arapça Anlam Eşleştirmeleri</text>\n  <rect x="35" y="46" width="200" height="90" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="135" y="70" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">الرَّحْمٰنُ - الرَّحِيمُ</text>\n  <text x="135" y="92" text-anchor="middle" font-size="11" fill="#1e3a8a">Er-Rahmân / Er-Rahîm</text>\n  <text x="135" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">كَثِيرُ الرَّحْمَةِ لِلْمُؤْمِنِينَ وَالْكَافِرِينَ</text>\n  <rect x="250" y="46" width="200" height="90" rx="8" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="14" font-weight="bold" fill="#047857">الْخَالِقُ - الرَّزَّاقُ</text>\n  <text x="350" y="92" text-anchor="middle" font-size="11" fill="#065f46">El-Hâlık / Er-Rezzâk</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#065f46">يَخْلُقُ الْكَائِنَاتِ وَيَرْزُقُ الْمَخْلُوقَاتِ</text>\n  <rect x="465" y="46" width="200" height="90" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="565" y="70" text-anchor="middle" font-size="14" font-weight="bold" fill="#b45309">الْعَلِيمُ - الْحَكِيمُ</text>\n  <text x="565" y="92" text-anchor="middle" font-size="11" fill="#78350f">El-Alîm / El-Hakîm</text>\n  <text x="565" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">يَعْلَمُ كُلَّ شَيْءٍ وَيَفْعَلُ بِحِكْمَةٍ</text>\n  <rect x="35" y="150" width="200" height="90" rx="8" fill="#fdf4ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="135" y="174" text-anchor="middle" font-size="14" font-weight="bold" fill="#7e22ce">السَّمِيعُ - الْبَصِيرُ</text>\n  <text x="135" y="196" text-anchor="middle" font-size="11" fill="#6b21a8">Es-Semî\' / El-Basîr</text>\n  <text x="135" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">يَسْمَعُ الْأَصْوَاتَ وَيُبْصِرُ الْأَشْيَاءَ</text>\n  <rect x="250" y="150" width="200" height="90" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="350" y="174" text-anchor="middle" font-size="14" font-weight="bold" fill="#b91c1c">الْغَفُورُ - التَّوَّابُ</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#991b1b">El-Gafûr / Et-Tevvâb</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#7f1d1d">يَغْفِرُ الذُّنُوبَ وَيَقْبَلُ التَّوْبَةَ</text>\n  <rect x="465" y="150" width="200" height="90" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="565" y="174" text-anchor="middle" font-size="14" font-weight="bold" fill="#0369a1">الْمَلِكُ - الْقُدُّوسُ</text>\n  <text x="565" y="196" text-anchor="middle" font-size="11" fill="#075985">El-Melik / El-Kuddûs</text>\n  <text x="565" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0c4a6e">صَاحِبُ الْمُلْكِ وَالْمُنَزَّهُ عَنِ النَّقَائِصِ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">Esmâ-i Hüsnâ İle İlgili Arapça Cümle ve Dua Kalıpları</text>\n  <rect x="40" y="48" width="620" height="60" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.6"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. İsim Cümlesi Kalıbı (الْمُبْتَدَأُ وَالْخَبَرُ): اللّٰهُ غَفُورٌ رَحِيمٌ</text>\n  <text x="350" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">اللّٰهُ (Mübtedâ - Merfû) + غَفُورٌ (Birinci Haber) + رَحِيمٌ (İkinci Haber) → "Allah çok bağışlayandır, çok merhamet edendir."</text>\n  <rect x="40" y="118" width="620" height="60" rx="10" fill="#ecfdf5" stroke="#10b981" stroke-width="1.6"/>\n  <text x="350" y="142" text-anchor="middle" font-size="13" font-weight="bold" fill="#047857">2. İnne Tekit Kalıbı (إِنَّ وَاسْمُهَا وَخَبَرُهَا): إِنَّ اللّٰهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#065f46">إِنَّ (Tekit edatı) + اللّٰهَ (İnne\'nin ismi - Mansûb) + قَدِيرٌ (İnne\'nin haberi - Merfû) → "Şüphesiz Allah her şeye kadirdir."</text>\n  <rect x="40" y="188" width="620" height="58" rx="10" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.6"/>\n  <text x="350" y="212" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">3. Nidâ ve Dua Kalıbı (أُسْلُوبُ النِّدَاءِ وَالدُّعَاءِ): يَا غَفَّارُ اغْفِرْ لِي  |  يَا رَزَّاقُ ارْزُقْنَا</text>\n  <text x="350" y="232" text-anchor="middle" font-size="11" fill="#78350f">يَا + Münâdâ (Damme üzere mebnî) + Emir/Dua Fiili → "Ey çok bağışlayan (Allah\'ım) beni bağışla! Ey rızık veren bizi rızıklandır!"</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
